 "content": "def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # The framed field's regular stripe pattern has a five-cell horizontal period.
    # Infer each row's phase from the intact cells, then restore only zero holes
    # inside the colored frame.
    vals=[1,3,5,7,9]
    # Inner patterned area is the rectangle bounded by color-4 frame where present.
    for r in range(h):
        candidates=[c for c in range(w) if g[r][c] in vals]
        if not candidates: continue
        # Establish residue mapping from observed cells by majority vote.
        mapping={}
        for residue in range(5):
            counts={v:0 for v in vals}
            for c in candidates:
                if c%5==residue: counts[g[r][c]]+=1
            mapping[residue]=max(vals,key=lambda v:counts[v])
        for c in range(w):
            if g[r][c]!=0: continue
            # Fill zeros only between the first and last established patterned cells.
            if min(candidates)<=c<=max(candidates):
                g[r][c]=mapping[c%5]
    return g
